import 'reflect-metadata';
import { NextResponse } from 'next/server';
import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';

import { RegisterRequest } from '../../../../lib/dto/register.dto';
import {
  accountExists,
  findUserByUsername,
  createUser,
} from '../../../../lib/store';
import { createCredential } from '../../../../lib/credentialsStore';
import { logger } from '../../../../lib/logger';

export async function POST(req: Request) {
  try {
    const body = await req.json();

    const dto = plainToInstance(RegisterRequest, body);

    const errors = await validate(dto, {
      whitelist: true,
      forbidNonWhitelisted: true,
    });

    if (errors.length > 0) {
      // Temporary debug: log validation details to help diagnose client errors.
      // These logs are intentionally concise and avoid exposing sensitive values.
      const validationDetails = errors.map((e) => ({
        property: e.property,
        constraints: e.constraints,
      }));
      logger.warn('Validation failed', { validationDetails });

      return NextResponse.json(
        {
          errorCode: 'VAL-422',
          message: 'Invalid input',
          details: validationDetails,
        },
        { status: 422 },
      );
    }

    // Username must be unique.
    const existing = await findUserByUsername(dto.username);

    if (existing) {
      return NextResponse.json(
        {
          errorCode: 'AUTH-409',
          message: 'Registration failed',
        },
        { status: 409 },
      );
    }

    // Registration must link to an existing trading account.
    // It must NOT create a trading account.
    const accountExistsForUser = await accountExists(dto.accountId);

    if (!accountExistsForUser) {
      return NextResponse.json(
        {
          errorCode: 'AUTH-409',
          message: 'Registration failed',
        },
        { status: 409 },
      );
    }

    /*
     * IMPORTANT:
     * createUser expects a password hash. The credential/password-hashing
     * component owns password hashing and the credentials table. Create a
     * credential (which hashes the plaintext) and pass the stored hash to
     * createUser. Never persist plaintext passwords.
     */
    const credential = await createCredential(dto.accountId, dto.username, dto.password);

    const user = await createUser(
      dto.username,
      credential.password_hash,
      dto.accountId,
    );

    const response = {
      id: user.id,
      username: user.username,
      accountId: user.accountId,
      roles: user.roles,
      createdOn: user.createdOn,
    };

    return NextResponse.json(response, { status: 201 });
  } catch (err) {
    // Do not log whole request objects or error stacks that may contain sensitive data.
    logger.error('Registration error', { message: (err as Error)?.message });

    return NextResponse.json(
      {
        errorCode: 'VAL-422',
        message: 'Invalid input',
      },
      { status: 422 },
    );
  }
}